/* 每个 id 独立 TLS 缓冲：每次调用都重新解密，无缓存、无线程竞争 */
static __thread char _obf_tls[OBF_COUNT][OBF_MAXLEN];
static char *_obf_dec(int id) {
    const _obf_ent_t *e = &_obf_tab[id];
    char *out = _obf_tls[id];
    for (uint16_t i = 0; i < e->len; i++) {
        volatile uint8_t s = (uint8_t)(e->k ^ OBF_SKEY((i + e->k) & 0xFF) ^ (uint8_t)(i * 31));
        out[i] = (char)(e->b[i] ^ s);
    }
    out[e->len] = 0;
    return out;
}
#define OBF(id) _obf_dec(id)

static void obf_fill(char *dst, size_t n, const char *src) {
    size_t i = 0;
    for (; src[i] && i + 1 < n; i++) dst[i] = src[i];
    dst[i] = 0;
}
static void obf_init_runtime(void) { }

/* 相邻字面量拼接：运行时拼（源码里 "a" "b" 会被拆成两个 id）*/
/* 手写拷贝而非 snprintf("%s%s")：避免 .rodata 里躺一个明文格式串 */
static char *obf_cat2(int a, int b) {
    static __thread char buf[256];
    char *p = buf; const char *s = OBF(a);
    while (*s && p < buf + 255) *p++ = *s++;
    s = OBF(b);
    while (*s && p < buf + 255) *p++ = *s++;
    *p = 0;
    return buf;
}
